export function bySeller(lines: Line[]) {
  const groups = Map.groupBy(lines, (l) => l.seller.id);
  return [...groups.values()].map((lines) => ({
    seller: lines[0].seller,
    lines,
    eta: latest(lines.map((l) => l.eta)),
  }));
}
